const D = { scale:1, energy:.7, hue:12, speed:1, density:.5, x:.5, y:.72, style:'poster', act:'chug', chub:.5, seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const md=(a,n)=>((a%n)+n)%n, frc=v=>v-Math.floor(v), clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const sn=(tt,o)=>{const f=Math.floor(tt),xq=tt-f;return (fr(f+o)*(1-xq)+fr(f+1+o)*xq-.5)*2;};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat;
S.lastBeat=K.beat;

const u=Math.min(width,height);
const bt=K.beat*P.speed;
const en=P.energy*(.55+.45*K.intensity);
const kick=K.pulse*.55+A.bass*.8;
const H=md(P.hue,360);
const pos=P.style==='poster', blue=P.style==='blueprint', eng=P.style==='engraving', noir=P.style==='noir';
