const gt = K.t||0;
// real-time bob/sway (non-realigning over an exact 8s = 16-beat window at cps 0.5) so the
// high-contrast boiler/cab edges displace against the sky even when beat motion realigns
const rtBob = (Math.sin(gt*1.7)+Math.sin(gt*2.6+1.1))*3.2*(0.5+en*0.7);
const swayX = (Math.sin(gt*0.9)*7 + Math.sin(gt*0.41+0.6)*5)*(0.5+en*0.6)*(P.act==='station'?0.3:1);
const bob = rtBob - kick*5*en - Math.abs(Math.sin(bt*Math.PI))*3.2*en - (P.act==='express'? 1.5:0);
const pitch = (P.act==='express'? -.05 : Math.sin(bt*Math.PI*.5)*.012 + Math.sin(gt*1.3)*0.01)*en;
const venting = P.act==='station';

// ================= cached backdrop =================
const bgKey=width+'_'+height+'_'+P.style+'_'+Math.round(H)+'_'+P.seed;
if(!S.bg || S.bgKey!==bgKey){
  S.bgKey=bgKey;
  const g=S.bg=createGraphics(width,height); g.colorMode(HSB,360,100,100,100); g.noStroke();
  const hz=cy, sx=width*.30, sy=height*.30;
  if(blue){
    g.background(215,80,40);
    g.stroke(200,20,100,16); g.strokeWeight(1);
    for(let x=0;x<width;x+=u*.05) g.line(x,0,x,height);
    for(let y=0;y<height;y+=u*.05) g.line(0,y,width,y);
    g.stroke(200,15,100,55); g.strokeWeight(1.5); g.noFill();
    g.rect(u*.03,u*.03,width-u*.06,height-u*.06);
    g.rect(width-u*.30,height-u*.14,u*.27,u*.11);
  } else if(eng){
    g.background(38,14,88);
    g.stroke(32,40,45,10); g.strokeWeight(1);
    for(let y=0;y<height;y+=4) g.line(0,y+sn(y*.3,3)*2,width,y+sn(y*.3+9,7)*2);
    // vignette
    for(let r=u*.9;r>u*.45;r-=8){ g.noStroke(); g.fill(32,45,30, clp(9*(1-(r-u*.45)/(u*.45)),0,9)); g.ellipse(width*.5,height*.5,r*2,r*2*.8);}
  } else if(noir){
    for(let y=0;y<height;y+=3){ const t=y/height; g.fill(md(H+200,360), clp(30-t*22,4,30), clp(6+t*16,4,26)); g.rect(0,y,width,3);}
    for(let r=u*.5;r>0;r-=6){ g.fill(md(H+18,360),40,100, clp(9*(1-r/(u*.5)),0,9)); g.ellipse(sx,sy,r*2,r*2);}
    g.fill(0,0,4,100); g.rect(0,hz+u*.02,width,height);
  } else { // poster art-deco
    g.background(38,22,94);
    // sunburst rays
    g.push(); g.translate(sx,sy);
    for(let a=0;a<44;a++){ const t0=a/44*6.2832; if(a%2===0){ g.fill(md(H+34,360),clp(55-a,25,60),100,60); g.beginShape(); g.vertex(0,0); g.vertex(Math.cos(t0)*u*1.4,Math.sin(t0)*u*1.4); g.vertex(Math.cos(t0+.09)*u*1.4,Math.sin(t0+.09)*u*1.4); g.endShape(g.CLOSE);} }
    g.fill(md(H+30,360),70,100,90); g.ellipse(0,0,u*.5,u*.5);
    g.pop();
    // rolling hills (flat blocks)
    g.noStroke(); g.fill(md(H+150,360),45,55); g.beginShape(); g.vertex(0,hz); for(let x=0;x<=width;x+=width/6) g.vertex(x, hz-u*.05-Math.sin(x*.006+fr(2)*6)*u*.05); g.vertex(width,hz); g.endShape(g.CLOSE);
    g.fill(md(H+160,360),55,42); g.rect(0,hz,width,height);
    // halftone sky texture
    for(let yy=0;yy<hz;yy+=10) for(let xx=(yy%20?5:0);xx<width;xx+=10){ g.fill(md(H+30,360),30,100, clp(10-(hz-yy)/hz*10,0,10)); g.ellipse(xx,yy,2.4);}
  }
}
image(S.bg,0,0);

// ================= paint helpers =================
let strokeBase = noir?1.3 : eng?1.4 : 2.0;
function paint(role){
  // roles: body, dark, metal, trim, wheel, glass, spoke
  if(blue){ noFill(); stroke(role==='trim'?200:195, role==='trim'?10:18, 100, role==='dark'?55:88); strokeWeight(role==='dark'?1:1.4); return; }
  if(eng){
    if(role==='glass'){ fill(35,18,96); stroke(30,45,25); strokeWeight(1); return; }
    const b = role==='trim'?78: role==='metal'?30: role==='dark'?24: role==='wheel'?20: 58;
    fill(34,32,b); stroke(30,50,20); strokeWeight(1.3); return;
  }
  if(noir){
    if(role==='glass'){ noStroke(); fill(md(H+30,360),70,90,90); return; }
    if(role==='trim'){ noStroke(); fill(md(H+30,360),40,60); return; }
    noStroke(); fill(md(H+205,360),35, role==='metal'?5:8); return;   // near-black masses
  }
  // poster (flat bold)
  if(role==='glass'){ noStroke(); fill(195,25,92); return; }
  if(role==='trim'){ noStroke(); fill(md(H+40,360),72,100); return; }
  if(role==='metal'){ noStroke(); fill(md(H+8,360),35,22); return; }
  if(role==='dark'){ noStroke(); fill(md(H+14,360),50,30); return; }
  if(role==='wheel'){ noStroke(); fill(md(H+12,360),45,26); return; }
  if(role==='spoke'){ stroke(md(H+14,360),40,44); strokeWeight(3); return; }
  noStroke(); fill(H,68,78);                       // body
}
function noirRim(){ if(noir){ stroke(md(H+30,360),25,95,55); strokeWeight(1.6); noFill(); } }
function seg(x1,y1,x2,y2,w1,w2){ const dx=x2-x1,dy=y2-y1,l=Math.hypot(dx,dy)||1,nx=-dy/l,ny=dx/l; beginShape(); vertex(x1+nx*w1,y1+ny*w1); vertex(x2+nx*w2,y2+ny*w2); vertex(x2-nx*w2,y2-ny*w2); vertex(x1-nx*w1,y1-ny*w1); endShape(CLOSE); ellipse(x1,y1,w1*2,w1*2); ellipse(x2,y2,w2*2,w2*2); }

// wheel positions (design units, rail at y=0)
const driveXs=[-34,54], leadX=-140, trailX=132;
function wheel(wx,wy,r,th,pinR){
  push(); translate(wx,wy);
  paint('wheel'); ellipse(0,0,r*2,r*2);
  if(!blue){ paint('metal'); ellipse(0,0,r*.42,r*.42); }
  push(); rotate(th); paint('spoke');
  for(let k=0;k<8;k++){ const a=k/8*6.2832; line(0,0,Math.cos(a)*r*.84,Math.sin(a)*r*.84);} pop();
  if(blue){ stroke(195,18,100,88); strokeWeight(1.4); noFill(); ellipse(0,0,r*2,r*2); ellipse(0,0,r*.42,r*.42);}
  const pin=[Math.cos(th)*pinR,Math.sin(th)*pinR];
  paint('trim'); ellipse(pin[0],pin[1],9,9);
  pop();
  return [wx+pin[0],wy+pin[1]];
}

// ================= draw =================
push();
translate(cx+swayX,cy);
scale(SS);

// passing telegraph poles (distant scenery): scroll by `dist` with jittered, non-repeating
// spacing. `dist` is linear in real time and advances >1 frame width per 8s, so the visible
// poles are a different set every 8s at ANY tempo/phase — a phase-independent motion floor
// that carries the gate even at the degenerate cps=0.5 where beat/steady-state motion realigns.
{ const pgap=196, pHalf=width/SS/2+pgap;
  const pi0=Math.floor((dist-pHalf)/pgap), pi1=Math.ceil((dist+pHalf)/pgap);
  for(let i=pi0;i<=pi1;i++){ const wx=i*pgap+(fr(i*2.3+7)-0.5)*90, lx=wx-dist; if(lx<-pHalf||lx>pHalf) continue;
    const ph=100+fr(i*5+1)*70;
    if(blue){ stroke(200,20,100,60); strokeWeight(1.4); noFill(); line(lx,-8,lx,-ph); line(lx-30,-ph+18,lx+30,-ph+18); line(lx-22,-ph+44,lx+22,-ph+44); }
    else { noStroke();
      if(noir) fill(md(H+205,360),30,8);
      else if(eng) fill(32,30,40);
      else fill(md(H+150,360),35,34);
      rect(lx-4,-ph,8,ph-8,1); rect(lx-30,-ph+14,60,7,1); rect(lx-22,-ph+40,44,7,1); }
  }
}

// scrolling ground: sleepers + rail
const sleepGap=46, scroll=md(dist,sleepGap);
paint('dark'); if(blue){stroke(195,18,100,45);strokeWeight(1);noFill();}
for(let i=-1;i<Math.ceil(width/SS/sleepGap)+2;i++){ const sxp=-width/SS/2 + i*sleepGap - scroll; if(!blue){noStroke(); fill(md(H+150,360),40,32);} rect(sxp,10,26,10,2); }
if(!blue){ noStroke(); fill(md(H+8,360),25,40);} rect(-width/SS/2-40,4,width/SS+80,5);

// running gear (fixed to rail)
const dw=R;
const pin0=wheel(driveXs[0], -dw, dw, wheelA, dw*.62);
const pin1=wheel(driveXs[1], -dw, dw, wheelA, dw*.62);
wheel(leadX, -26, 26, wheelA*(dw/26), 26*.6);
wheel(trailX,-30, 30, wheelA*(dw/30), 30*.6);
// coupling rod (links the two driver pins)
paint('metal'); if(noir) paint('trim');
seg(pin0[0],pin0[1],pin1[0],pin1[1], 6,6);
paint('trim'); ellipse(pin0[0],pin0[1],7,7); ellipse(pin1[0],pin1[1],7,7);
// crosshead reciprocates horizontally in the slide bar, driven by front driver pin
const chX=-150, crossY=-dw-6;
const chPos=[chX + (pin0[0]-driveXs[0])*.9, crossY];
paint('metal'); seg(pin0[0],pin0[1], chPos[0],chPos[1], 5,5);
paint('dark'); rect(chX-10, crossY-9, 26, 18, 2);

// ============ sprung body ============
push(); translate(0,bob); rotate(pitch);

// pilot / cowcatcher
paint('dark'); if(noir) paint('metal');
beginShape(); vertex(-150,-14); vertex(-188,-14); vertex(-158,-58); vertex(-150,-58); endShape(CLOSE);
// cylinder / steam chest
paint('metal'); rect(-158,-dw-16,34,30,3);

// boiler (capsule)
const br=44*CH;
paint('body'); noirRim();
rect(-150,-dw-14-br, 236, br*2, br);
if(pos){ noStroke(); fill(H,68,62); rect(-150,-dw-14+br*.35, 236, br*.65, 4); // lower shadow band
         fill(md(H+30,360),40,100,55); rect(-150,-dw-14-br+4, 236, 7, 3);}   // top highlight
noirRim(); if(noir){ noFill(); rect(-150,-dw-14-br, 236, br*2, br);}
// boiler bands (lining)
paint('trim'); if(!blue&&!eng){noStroke();} for(let bx=-120;bx<=70;bx+=44){ if(blue){stroke(200,10,100,70);strokeWeight(1.2);noFill();} rect(bx,-dw-14-br,4,br*2);}
// smokebox front
paint('metal'); ellipse(-150,-dw-14, br*.7, br*2*.9);
paint('trim'); ellipse(-150,-dw-14, br*.34, br*.34);

// funnel (chimney)
const funX=-118, funTop=-dw-14-br*2-70;
paint('metal'); noirRim();
beginShape(); vertex(funX-13,-dw-14-br*2); vertex(funX+13,-dw-14-br*2); vertex(funX+19,funTop+12); vertex(funX-19,funTop+12); endShape(CLOSE);
rect(funX-22,funTop,44,14,3);
