paint('metal'); arc(-30,-dw-14-br*2, 42,44, Math.PI,6.2832,CHORD); rect(-51,-dw-14-br*2,42,10);
paint('trim'); if(!blue){noStroke();} ellipse(-30,-dw-14-br*2, 12,12);
// whistle
paint('trim'); rect(6,-dw-14-br*2-14,4,16,1);

// cab
const cabX=64, cabTop=-dw-14-br*2-30, cabMid=-dw-14-br*1.2;
paint('body'); noirRim();
rect(cabX, cabMid, 92, br*1.2, 4);
rect(cabX, cabTop, 92, cabMid-cabTop, 6);
// cab roof
paint('dark'); rect(cabX-6, cabTop-8, 104, 14, 4);
// cab window
paint('glass'); rect(cabX+16, cabTop+14, 40, 34, 3);
if(pos){ noStroke(); fill(md(H+14,360),50,30); rect(cabX, -dw-2, 92, br*.5,3);} // cab underframe shadow

pop(); // end sprung body
pop(); // end loco transform

// ================= smoke / steam (screen space) =================
const funWX = cx + swayX + funX*SS, funWY = cy + (funTop+8+bob)*SS;
blendMode(noir?ADD:BLEND); noStroke();
// Continuous REAL-TIME emission: the plume re-forms off K.t (not the beat), so it genuinely
// evolves across any 8s window — even the degenerate cps=0.5 (=16 beats) where beat motion
// realigns. Dark, billowing, high-contrast smoke on the light liveries = the dominant mover.
const emitRate = (P.act==='station'? 2.2 : 3.4) * (0.7 + en*0.5);   // puffs/sec (real-time)
const nowE = gt * emitRate;
const puffN = P.act==='station'? 12 : 20;
const lifeS = 3.0;                                       // puff lifetime (seconds)
for(let k=0;k<puffN;k++){
  const ei = Math.floor(nowE) - k; if(ei<0) continue;
  const age = (nowE - ei) / emitRate;                   // seconds since emitted (real-time)
  if(age>lifeS) continue;
  const t=clp(age/lifeS,0,1);
  const beatPop = k===0 ? kick*0.6 : 0;                 // youngest puff jumps on the beat
  const back = age*drift*150*SS*(.6+en*.6);             // wide horizontal drift back
  const rise = (age*58 + Math.pow(age,1.35)*20)*SS;     // billows up
  const wob  = sn(age*1.5, ei*3)*26*SS*(1-t);
  const px = funWX - back*(P.act==='station'?.2:1) + wob;
  const py = funWY - rise;
  const grow = (34 + age*92 + fr(ei)*22)*SS*(.8+en*.5)*(1+beatPop);   // big billows
  const al = clp((1-t*t)*(noir?66:80), 0, 84);
  if(noir) fill(md(H+30,360),18,100,al*.85);            // bright steam on dark bg (ADD)
  else if(blue) fill(200,24,100,al*.82);                // light steam on dark blueprint
  else if(eng) fill(32,34,clp(44-age*7,20,44),al*.95);  // dark ink smoke on cream engraving
  else fill(md(H+16,360), clp(28+age*5,20,48), clp(42-age*10,15,42), al); // dark sooty poster smoke
  ellipse(px,py,grow,grow*.94);
  // darker core / rim for body & texture
  if(noir||blue){ fill(noir?md(H+30,360):200, blue?16:12, 100, al*.5); ellipse(px-grow*.16,py-grow*.14,grow*.5,grow*.5); }
  else { fill(md(H+16,360), 42, clp(30-age*8,14,30), al*.6); ellipse(px+grow*.14,py+grow*.12,grow*.5,grow*.5); }
}
// station cylinder steam vents (horizontal jets) + whistle plume
if(venting){
  const vfX=cx+swayX+(-150)*SS, vfY=cy+(-R-4+bob)*SS;
  for(let k=0;k<7;k++){ const ph=frc(K.t*1.1+fr(k*3)); const jx=vfX-ph*150*SS - fr(k)*20*SS; const jy=vfY+Math.sin(ph*3+k)*10*SS + (fr(k*7)-.5)*20*SS; const a2=clp((1-ph)*60,0,60);
    fill(md(H+30,360),6,100,a2); ellipse(jx,jy,(6+ph*22)*SS,(6+ph*22)*SS*.7);}
  const wfX=cx+swayX+8*SS, wfY=cy+(-R-14-CH*88+bob)*SS;
  for(let k=0;k<6;k++){ const ph=frc(K.t*.7+fr(k*5)); fill(md(H+30,360),8,100,clp((1-ph)*55,0,55)); ellipse(wfX+ (fr(k)-.5)*30*SS, wfY-ph*160*SS, (5+ph*16)*SS,(5+ph*16)*SS);}
}
// express speed streaks
if(P.act==='express'){ stroke(noir?md(H+30,360):0,0,100, 40); for(let k=0;k<6;k++){ strokeWeight(2*SS); const yy=cy+(-R-fr(k*2)*140-6+bob)*SS; const xx=cx+swayX-(120+fr(k*3)*180)*SS - frc(K.t*4+fr(k))*120*SS; line(xx,yy,xx-90*SS,yy);} noStroke(); }
